set -euo pipefail
cd /home/ubuntu/apps/travel-planner
echo  | base64 -d > rag/eval/reports/routing_challenge_v1_run1.json
echo  | base64 -d > rag/eval/reports/routing_challenge_v1_run1.md
echo  | base64 -d > rag/eval/reports/routing_challenge_v1_run1_unreviewed.json
echo  | base64 -d > rag/eval/reports/routing_challenge_v1_run1_unreviewed.md
echo  | base64 -d > docs/ROUTING_CHALLENGE_2026-10-12.md
echo  | base64 -d > docs/PROJECT_MEMORY.md
echo  | base64 -d > docs/PROJECT_STATUS_AND_ARCHITECTURE.md
echo  | base64 -d > docs/MIXED_QUERY_DESIGN.md
.venv/bin/python - <<'PY'
import json,hashlib
from pathlib import Path
p=Path('rag/eval/reports')
r=json.loads((p/'routing_challenge_v1_run1.json').read_text())
u=json.loads((p/'routing_challenge_v1_run1_unreviewed.json').read_text())
assert [c['response'] for c in r['cases']]==[c['response'] for c in u['cases']]
assert len(r['cases'])==30 and all(c['human_review'] for c in r['cases'])
m=json.loads(Path('rag/eval/baselines/routing_v2_frozen/manifest.json').read_text())
for name,sha in m['files'].items():
    assert hashlib.sha256(Path(name).read_bytes()).hexdigest()==sha,name
print('Verified 30 user reviews, unchanged answer payloads and frozen service source hashes')
print(json.dumps(r['human_review_summary']['all_cells']))
PY
cp rag/eval/reports/routing_challenge_v1_run1.md /home/ubuntu/portfolio/downloads/rag/routing-evaluation-30-2026-10-12.md
chmod 644 /home/ubuntu/portfolio/downloads/rag/routing-evaluation-30-2026-10-12.md
sha256sum rag/eval/reports/routing_challenge_v1_run1.md
curl -fsS --max-time 15 http://52.199.126.245/downloads/rag/routing-evaluation-30-2026-10-12.md | sha256sum
